using AiGateway.Application;using AiGateway.Application.IntentRouting;using AiGateway.Application.Orchestration;using AiGateway.Application.Prompting;using AiGateway.Application.Retrieval;using AiGateway.Application.Validation;using AiGateway.Infrastructure.Mcp;using AiGateway.Infrastructure.Observability;using AiGateway.Infrastructure.Ollama;using AiGateway.Infrastructure.Security;using Microsoft.Extensions.Options;
namespace AiGateway.Infrastructure;
public static class DependencyInjection
{public static IServiceCollection AddAiGateway(this IServiceCollection services,IConfiguration configuration){services.AddOptions<AiGatewayOptions>().Bind(configuration.GetSection(AiGatewayOptions.SectionName)).ValidateDataAnnotations().ValidateOnStart();services.AddOptions<KnowledgeBaseMcpOptions>().Bind(configuration.GetSection(KnowledgeBaseMcpOptions.SectionName)).ValidateDataAnnotations().Validate(options=>options.ServerName=="supabase-mcp-server_kb","A Fase 1 aceita somente supabase-mcp-server_kb.").ValidateOnStart();services.AddOptions<OllamaOptions>().Bind(configuration.GetSection(OllamaOptions.SectionName)).ValidateDataAnnotations().ValidateOnStart();services.AddSingleton<KnowledgeBaseMcpClient>();services.AddSingleton<IKnowledgeBaseMcpClient>(sp=>sp.GetRequiredService<KnowledgeBaseMcpClient>());services.AddSingleton<IIntentCatalog>(sp=>sp.GetRequiredService<KnowledgeBaseMcpClient>());services.AddSingleton<IKnowledgeRepository>(sp=>sp.GetRequiredService<KnowledgeBaseMcpClient>());services.AddHttpClient<OllamaClient>((sp,client)=>{var value=sp.GetRequiredService<IOptions<OllamaOptions>>().Value;client.BaseAddress=new Uri(value.Endpoint.TrimEnd('/')+"/");client.Timeout=Timeout.InfiniteTimeSpan;});services.AddHttpClient<OllamaHealthCheck>((sp,client)=>{var value=sp.GetRequiredService<IOptions<OllamaOptions>>().Value;client.BaseAddress=new Uri(value.Endpoint.TrimEnd('/')+"/");client.Timeout=TimeSpan.FromSeconds(Math.Min(3,value.TimeoutSeconds));});services.AddTransient<ILanguageModelClient>(sp=>sp.GetRequiredService<OllamaClient>());services.AddTransient<IEmbeddingClient>(sp=>sp.GetRequiredService<OllamaClient>());services.AddSingleton<ITokenEstimator,ApproximateTokenEstimator>();services.AddSingleton<ISensitiveDataSanitizer,SensitiveDataSanitizer>();services.AddSingleton<IAiTelemetry,AiTelemetry>();services.AddScoped<IIntentRouter,RuleBasedIntentRouter>();services.AddScoped<IKnowledgeRetriever,HybridKnowledgeRetriever>();services.AddScoped<IPromptBuilder,GroundedPromptBuilder>();services.AddScoped<IResponseValidator,CitationResponseValidator>();services.AddScoped<IAiOrchestrator,AiOrchestrator>();services.AddHealthChecks().AddCheck<KnowledgeBaseMcpHealthCheck>("mcp-kb").AddCheck<OllamaHealthCheck>("ollama");return services;}}
